mapper.select:
SELECT COALESCE(MAX(sort_order) + 1, 0)
FROM task
WHERE status = #{status}

SELECT COUNT(*)
FROM task
WHERE status = #{status}
  AND id <> #{excludeId}

mapper.update:
UPDATE task
SET sort_order = sort_order - 1
WHERE status = #{status}
  AND sort_order > #{position}
  AND id <> #{excludeId}

UPDATE task
SET sort_order = sort_order + 1
WHERE status = #{status}
  AND sort_order >= #{position}
  AND id <> #{excludeId}
